// lib
// Project A: no reference to MessagePack at all.
namespace ProjectA
{
    public class MyType
    {
        public int Id { get; set; }

        public string? Name { get; set; }
    }
}

// app
// Project B: references Project A and MessagePack (with MessagePack.SourceGenerator as analyzer).
using System;
using MessagePack;
using MessagePack.Formatters;
using ProjectA;

namespace ProjectB
{
    // Old: CS0246, GeneratedMessagePackFormatterAttribute does not exist, and the generator has
    //      only two RegisterSourceOutput pipelines, so no body is ever produced for this class.
    // New: the third RegisterSourceOutput pipeline emits the Serialize/Deserialize implementation
    //      of this partial class (string keys for the public read/write members of MyType)
    //      and registers it in GeneratedMessagePackResolver.
    [GeneratedMessagePackFormatter]
    internal partial class MyTypeFormatter : IMessagePackFormatter<MyType>;

    internal static class Program
    {
        private static void Main()
        {
            MessagePackSerializerOptions options =
                MessagePackSerializerOptions.Standard.WithResolver(GeneratedMessagePackResolver.Instance);

            byte[] bytes = MessagePackSerializer.Serialize(new MyType { Id = 7, Name = "seven" }, options);
            MyType result = MessagePackSerializer.Deserialize<MyType>(bytes, options);

            // New build prints: 82 7 seven MyTypeFormatter  (0x82 = map with two string keys)
            Console.WriteLine(
                $"{bytes[0]:X2} {result.Id} {result.Name} {GeneratedMessagePackResolver.Instance.GetFormatter<MyType>()!.GetType().Name}");
        }
    }
}
